{"code": "BEGIN {
  FS=OFS="\t"
}
NR == 1 {
  # Print the first header as it is
  printf "%s", $1
  # Adjust the remaining original headers to only include the part before the first underscore
  for (i = 2; i <= NF; i++) {
    split($i, header_parts, "_")
    printf "\t%s", header_parts[1]
  }
  printf "\n"
}
NR > 1 {
  # Print the rest of the lines as they are
  for (i = 1; i <= NF; i++) {
    printf "%s%s", $i, (i < NF ? OFS : ORS)
  }
}", "infile": {"__class__": "ConnectedValue"}, "__page__": null, "__rerun_remap_job_id__": null}

{"code": "BEGIN {
  FS=OFS="\t"
}
NR == 1 {
  # Print the renamed headers for the new columns
  printf "superkingdom\tkingdom\tphylum"
  # Adjust the remaining original headers to only include the part before the first underscore
  for (i = 2; i <= NF; i++) {
    split($i, header_parts, "_")
    printf "\t%s", header_parts[1]
  }
  printf "\n"
}
NR > 1 {
  # Split the first column by ';' into three parts
  split($1, taxa_parts, ";")
  superkingdom = (taxa_parts[1] != "" ? taxa_parts[1] : "unassigned")
  kingdom = (length(taxa_parts[2]) ? taxa_parts[2] : "unassigned")
  phylum = (length(taxa_parts[3]) ? taxa_parts[3] : "unassigned")
  printf "%s\t%s\t%s", superkingdom, kingdom, phylum
  # Process the remaining columns
  for (i = 2; i <= NF; i++) {
    if ($i != "") {
      split($i, part, "_")
      printf "\t%s", part[1]
    } else {
      printf "\tunassigned"
    }
  }
  printf "\n"
}", "infile": {"__class__": "ConnectedValue"}, "__page__": null, "__rerun_remap_job_id__": null}
